import { useNavigate, Link } from "react-router-dom";

export default function AuthLayout({ children, leftContent, leftBg = "bg-red" }) {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen flex flex-col bg-white">
      {/* Top bar */}
      <div className="h-14 px-8 flex items-center justify-between border-b border-gray-200">
        <Link to="/" className="flex items-center gap-2">
          <div className="w-8 h-8 bg-red rounded-lg flex items-center justify-center text-white font-bold text-sm">
            A
          </div>
          <span className="font-semibold text-gray-900">WorkBridge DZ</span>
        </Link>
        <button
          onClick={() => navigate(-1)}
          className="text-sm text-gray-400 hover:text-gray-900 transition-colors"
        >
          ← Back
        </button>
      </div>

      {/* Body */}
      <div className="flex flex-1">
        {/* Left panel */}
        <div className={`w-[40%] ${leftBg} p-16 flex flex-col justify-end`}>
          {leftContent}
        </div>

        {/* Right panel */}
        <div className="flex-1 bg-cream flex flex-col justify-center px-20 py-12">
          {children}
        </div>
      </div>
    </div>
  );
}
